///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 로그인 사용자정보로 공시처리가능여부 체크
        await scwin.getProcButtonYN();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_AcptProcs",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_AcptProcs=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10009.onpageload" });
    }
};

