 * @returns {void}
 * @hidden N
 */
scwin.dts_btnshow_OnLoadCompleted = function(rowcount) {
    try {
        scwin.showProcButton(dts_btnshow.getCellData(1, "DUTY_PROC_YN"), dts_btnshow.getCellData(1, "GRNL_PROC_YN"), dts_btnshow.getCellData(1, "CLOSE_YN"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10009.dts_btnshow_OnLoadCompleted" });
    }
};

