///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getProcButtonYN
 * @description 로그인 사용자정보로 공시처리가능여부 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcButtonYN = async function() {
    const sbmOptions = {
        id : "sbm_dts_btnshow",
        action : "/Viewer.do",
        ref : "",
        target : "dts_btnshow=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name dsclStudy
 * @description 검토처리하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclStudy = async function() {
    // alert(vTrnsmtp +"="+gAcptNo);
    if (scwin.gAcptNo === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "TRNSM_TP_CD", "1"); // 선물공시는 1:전송으로 함.
    dts_AcptProcs.setCellData(1, "NXTDD_TDD_TP", "2"); // 선물공시는 2:당일으로 함.
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    const vMethod = "processDisclosureStudy";
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    const vAnswer = confirm('검토처리 하시겠습니까?');
    if (vAnswer === true) {
        if (await scwin.getProcsSate(scwin.gAcptNo) === false) {
            scwin.closeParentReload();
            return false;
        } else {
            trs_AcptProcs.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_AcptProcs",
                action : "/DisclosureStudy.do",
                ref : "dts_AcptProcs",
                target : "trs_AcptProcs=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name getProcsSate
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcsSate = async function(gAcptNo) {
    const sbmOptions = {
        id : "sbm_dts_procs_stat",
        action : "/Viewer.do",
        ref : "",
        target : "dts_procs_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");
    if (vBLOCK_YN === 'Y') {
        await $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    } else {
        return true;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showProcButton
 * @description 처리버튼 생성여부
 * @param {String} pDutyProcYn pDutyProcYn
 * @param {String} pGrnlProcYn pGrnlProcYn
 * @param {String} pCloseYn pCloseYn
 * @returns {void}
 * @hidden N
 */
scwin.showProcButton = function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    // alert(gDutyYn+","+pDutyProcYn+","+pGrnlProcYn+","+pCloseYn+","+gJobTitle);

    if (scwin.gAcptNo !== '') {
        // 가져온접수번호가 있으면 처리함.
        // 마감전일때
        if (pCloseYn === 'N') {
            if (scwin.gJobTitle === '40') {
                // 부서장권한 제거 2013.03.26
                panel_1.hide();
            } else {
                // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
                if ((scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') && pDutyProcYn === 'Y') {
                    // 패널라운드 처리
                    $c.libRoundPanel.PanelToGroupBox(panel_1);
                    panel_1.show("");
                } else {
                    // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                    // if (gJobTitle == '09' || gJobTitle == '40') {
                    if (scwin.gJobTitle === '09') {
                        // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.(팀장은 담당종목팀만 처리가능으로 변경 2013.03.26)
                        $c.libRoundPanel.PanelToGroupBox(panel_1); // 패널라운드 처리
                        panel_1.show("");
                    } else {
                        // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                        if (pGrnlProcYn === 'Y') {
                            $c.libRoundPanel.PanelToGroupBox(panel_1); // 패널라운드 처리
                            panel_1.show("");
                        } else {
                            panel_1.hide();
                        }
                    }
                }
            }
        } else {
            // 마감후일때
            panel_1.hide();
        }
    }
};

/**
 * @method
 * @name closeParentReload
 * @description 뷰어 닫고,  검색목록 reload
 * @returns {void}
 * @hidden N
 */
scwin.closeParentReload = function() {
    // 화면닫기
    $c.frame.path("../").fn_PvdSearch();
    $c.frame.path("../").fn_CloseWin();
};
